 static void ReleaseInjected(){if(injected||State("KEY")){Send(new Event{Type=1,Data=new Payload{Key=new Keyboard{Key=32,Flags=2}}});injected=false;State("KEY",false);Mark("key-state","up");Mark("key-released","fixture Space released");}}
 static StageENativeInputPlay(){if(AssetDatabase.IsAssetImportWorkerProcess()||Environment.GetEnvironmentVariable("SDK_E_NATIVE_INPUT")!="1")return;EditorApplication.update+=Tick;
  AssemblyReloadEvents.beforeAssemblyReload+=()=>{ReleaseInjected();var entry=ReloadEvent("before");if(State("REQUESTED")&&!State("RESTARTED")&&!EditorApplication.isPlaying){State("EXPLICIT_BEFORE",true);Mark("before-reload",entry.ToString());}};
  AssemblyReloadEvents.afterAssemblyReload+=()=>{var entry=ReloadEvent("after");if(State("REQUESTED")&&State("EXPLICIT_BEFORE")&&!State("RESTARTED")&&!EditorApplication.isPlaying){State("RELOADED",true);Mark("after-reload",entry.ToString());}};
  EditorApplication.playModeStateChanged+=state=>{if(state!=PlayModeStateChange.EnteredEditMode||!State("STOPPING")||State("REQUESTED")||State("SKIP_READY"))return;ReleaseInjected();var owned=EditorUtility.InstanceIDToObject(SessionState.GetInt("SDK_NATIVE_VIEW",0)) as EditorWindow;if(owned)owned.Close();Mark("entered-edit","active source stopped");if(Environment.GetEnvironmentVariable("SDK_E_SKIP_INPUT_RELOAD")=="1"){Mark("reload-skipped","negative fixture: restart without explicit reload");State("SKIP_READY",true);return;}State("REQUESTED",true);EditorUtility.RequestScriptReload();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);};
 }
 public static void Run(){foreach(string key in new[]{"KEY","STOPPING","REQUESTED","RELOADED","RESTARTED","SKIP_READY","EXPLICIT_BEFORE"})State(key,false);SessionState.SetInt("SDK_NATIVE_EVENT_SEQUENCE",0);File.WriteAllText(Path.Combine(Output,"reload-events.jsonl"),"");File.WriteAllText(Path.Combine(Output,"reload-events-process-"+System.Diagnostics.Process.GetCurrentProcess().Id+".jsonl"),"");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);new GameObject("native input author").AddComponent<StageENativeInputAuthor>();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/InputPlay.unity");File.WriteAllText(Path.Combine(Output,"started"),"native input Play fixture");EditorApplication.isPlaying=true;}
 static void Send(params Event[] events){foreach(var item in events){bool keyDown=item.Type==1&&(item.Data.Key.Flags&2)==0;bool mouseDown=item.Type==0&&(item.Data.Mouse.Flags&2)!=0;if(!keyDown&&!mouseDown)continue;GetWindowThreadProcessId(GetForegroundWindow(),out var foreground);if(foreground!=System.Diagnostics.Process.GetCurrentProcess().Id)throw new Exception("fixture-lost-foreground-before-injection");if(mouseDown){if(!GetCursorPos(out var point))throw new Exception("fixture-cursor-unavailable");GetWindowThreadProcessId(WindowFromPoint(point),out var pointed);if(pointed!=foreground)throw new Exception("fixture-cursor-outside-owned-window");}if(keyDown){if((GetAsyncKeyState(32)&0x8000)!=0)throw new Exception("fixture-Space-already-held");injected=true;State("KEY",true);Mark("key-state","down");}}if(SendInput((uint)events.Length,events,Marshal.SizeOf(typeof(Event)))!=events.Length)throw new Exception("native-input-send-failed");}
 static void Tick(){if(string.IsNullOrEmpty(Output)||!File.Exists(Path.Combine(Output,"started")))return;if(!EditorApplication.isPlaying){if(Reload&&(State("RELOADED")||State("SKIP_READY"))&&!State("RESTARTED")){State("RESTARTED",true);EditorApplication.EnterPlaymode();}return;}try{
  if(started==0)started=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-started>20)throw new TimeoutException("native-Play-input-deadline-phase-"+phase);
  if(phase==0){if(Environment.GetEnvironmentVariable("SDK_E_NO_INPUT_ADAPTER")=="1"){var capabilities=typeof(SpatialWallpaper.Sdk.Input).Assembly.GetType("SpatialWallpaper.Sdk.Editor.PlayCapabilities");if(capabilities==null)capabilities=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("SpatialWallpaper.Sdk.Editor.PlayCapabilities")).First(t=>t!=null);((IDisposable)capabilities.GetField("input",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)).Dispose();}
   var type=typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView",true);view=(EditorWindow)ScriptableObject.CreateInstance(type);view.position=new Rect(100,100,640,400);view.ShowUtility();view.Focus();SessionState.SetInt("SDK_NATIVE_VIEW",view.GetInstanceID());File.WriteAllText(Path.Combine(Output,State("RESTARTED")?"ready-second":"ready"),"ordinary Play author and native Game View ready");
   File.WriteAllText(Path.Combine(Output,"gameview-members.txt"),string.Join("\n",type.GetMembers(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static).Select(m=>m.MemberType+" "+m.Name)));phase=1;frames=0;return;}
  if(++frames<30)return;
  var author=UnityEngine.Object.FindObjectOfType<StageENativeInputAuthor>();if(author==null)throw new Exception("native-Play-author-missing");
  if(phase==1){float scale=EditorGUIUtility.pixelsPerPoint;var center=view.position.center;var point=new Point{X=(int)(center.x*scale),Y=(int)(center.y*scale)};IntPtr hwnd=WindowFromPoint(point);uint thread=GetWindowThreadProcessId(hwnd,out var pid);File.WriteAllText(Path.Combine(Output,"window.json"),new JObject{{"hwnd",hwnd.ToInt64()},{"thread",thread},{"currentThread",GetCurrentThreadId()},{"process",pid},{"rect",view.position.ToString()},{"scale",scale}}.ToString());SetForegroundWindow(GetAncestor(hwnd,2));view.Focus();SetCursorPos(point.X,point.Y);phase=2;frames=0;return;}
  if(phase==2){if(author.focused||author.held)throw new Exception("hover-acquired-Play-input");Send(new Event{Data=new Payload{Mouse=new Mouse{Flags=2}}},new Event{Data=new Payload{Mouse=new Mouse{Flags=4}}});File.WriteAllText(Path.Combine(Output,"clicked"),"real native click injected");phase=3;frames=0;return;}
  if(phase==3){if(!author.focused)throw new Exception("ordinary-Play-real-click-did-not-acquire-input");Send(new Event{Type=1,Data=new Payload{Key=new Keyboard{Key=32}}});injected=true;State("KEY",true);phase=4;frames=0;return;}
  if(phase==4){if(!author.held||!author.focused||author.downs!=1||author.unstable)throw new Exception("ordinary-Play-real-Space-not-observed");if(Reload&&!State("STOPPING")){Mark("active-before-stop","focused=True held=True downs=1");State("STOPPING",true);EditorApplication.ExitPlaymode();phase=11;return;}if(State("RESTARTED"))Mark("restarted-input","fresh native click and Space after explicit reload");ReleaseInjected();phase=5;frames=0;return;}
  if(phase==5){if(author.held||author.ups!=1||author.downs!=1||author.unstable)throw new Exception("ordinary-Play-release-edge-failed");SetCursorPos((int)view.position.center.x,(int)view.position.y+5);phase=6;frames=0;return;}
  if(phase==6){if(author.focused||author.x!=0||author.y!=0)throw new Exception("Game-View-toolbar-did-not-revoke");var center=view.position.center;SetCursorPos((int)center.x,(int)center.y);phase=7;frames=0;return;}
  if(phase==7){if(author.focused)throw new Exception("returning-from-toolbar-reacquired-without-click");Send(new Event{Data=new Payload{Mouse=new Mouse{Flags=2}}},new Event{Data=new Payload{Mouse=new Mouse{Flags=4}}});phase=8;frames=0;return;}
